function.arguments:
{"script":"const cards = document.querySelectorAll('[id^="mntl-recipe-card-meta_"]');
const results = [];
cards.forEach(card => {
  const starsDiv = card.querySelector('[id^="mntl-recipe-star-rating_"]');
  const link = card.closest('a');
  const title = card.querySelector('span')?.innerText;
  const stars = starsDiv ? Array.from(starsDiv.querySelectorAll('svg')).map(svg => svg.getAttribute('aria-label') || svg.getAttribute('class') || svg.outerHTML.substring(0, 100)).join('|') : '';
  const text = card.innerText.replace(/\n/g, ' | ');
  results.push({title: title, text: text, stars: stars.substring(0, 200)});
});
return JSON.stringify(results, null, 2);"}

