{"script":"const cards = document.querySelectorAll('[id^="mntl-card-list-card--extendable_"]');
const results = [];
cards.forEach(card => {
  const titleSpan = card.querySelector('.card__title') || card.querySelector('[class*="title"]') || card.querySelectorAll('span')[card.querySelectorAll('span').length - 1];
  const meta = card.querySelector('[id^="mntl-recipe-card-meta_"]');
  const starsDiv = meta ? meta.querySelector('[id^="mntl-recipe-star-rating_"]') : null;
  const ratingValue = starsDiv ? starsDiv.getAttribute('data-rating') || starsDiv.getAttribute('data-star-rating') || starsDiv.getAttribute('aria-label') : null;
  const ratingText = meta ? meta.innerText : '';
  const url = card.getAttribute('href');
  results.push({
    title: titleSpan ? titleSpan.innerText : null,
    url: url,
    ratingValue: ratingValue,
    ratingText: ratingText
  });
});
return JSON.stringify(results, null, 2);"}

